<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserProfile\Domain\ValueObject\Accessor\UserProfileZoneinfoAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserProfileZoneinfoAccessor trait.
 *
 * Covers null default, string/VO assignment via withZoneinfo,
 * getZoneinfo/zoneinfo accessors, and isZoneinfoChanged with/without original.
 */
class UserProfileZoneinfoAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withZoneinfo creates a new instance with the Zoneinfo set
     * from a string value, and getZoneinfo returns the primitive string.
     */
    public function testWithZoneinfoFromString(): void
    {
        // Arrange
        $holder = new ImplWithUserProfileZoneinfoAccessorUnitTest();

        // Act
        $result = $holder->withZoneinfo('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getZoneinfo());
    }
    /**
     * Asserts that withzoneinfo has access to the value object
     * from a string value, and getZoneinfo returns the primitive string.
     */
    public function testWithZoneinfoFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithUserProfileZoneinfoAccessorUnitTest();

        // Act
        $result = $holder->withZoneinfo('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->zoneinfo()->value());
    }
    public function testChangedZoneinfo(): void
    {
        // Arrange
        $holder = new ImplWithUserProfileZoneinfoAccessorUnitTest();
        $original = $holder->withZoneinfo('one');
        $same = $holder->withZoneinfo('one');
        $modified = $holder->withZoneinfo('other');

        // Act
        $unchanged = $holder->isZoneinfoChanged();
        $withSame = $original->isZoneinfoChanged($same);
        $withDiferent = $original->isZoneinfoChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithUserProfileZoneinfoAccessorUnitTest
{
    use UserProfileZoneinfoAccessor;
}
